insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('voice-ladder','Raised his voice ≠ Snapped ≠ Shouted ≠ Yelled ≠ Screamed',1,0,'All are louder than talking, but very different: raising your voice is louder once; snapping is a sudden short sharp word; shouting is loud (maybe happy, maybe angry); yelling is loud AND angry, often for a while; screaming is very loud, high and out of control.','كلها أعلى من الكلام العادي لكنها مختلفة جدًا: رفع الصوت مرة واحدة، والشخط كلمة قصيرة حادة مفاجئة، والصياح صوت عالٍ قد يكون فرحًا أو غضبًا، والصراخ عليه غاضب وقد يطول، والصراخ الهستيري عالٍ جدًا وخارج عن السيطرة.','A dad who says ''Enough!'' loudly once raised his voice; he did not scream.',null,90) on conflict (key) do update set title=excluded.title, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
insert into public.word_difference_parts (diff_key, word_id, explain, explain_ar, position) select 'voice-ladder', (select id from public.words where lang = 'en' and lower(headword) = lower('Raised his voice') order by (sense = '') desc limit 1), 'Louder, once, to be heard or to stop something.', 'رفع صوته', 0 on conflict (diff_key, word_id) do update set explain = excluded.explain, explain_ar = excluded.explain_ar, position = excluded.position;
update public.words set tags = (select array(select distinct x from unnest(tags || array['≠ Raised his voice ≠ Snapped ≠ Shouted ≠ Yelled ≠ Screamed']) x order by x)) where id = (select id from public.words where lang = 'en' and lower(headword) = lower('Raised his voice') order by (sense = '') desc limit 1);
