insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('moment-personality','Snapped at (a moment) ≠ Short-tempered (a personality) ≠ Abusive (a pattern)',1,0,'What someone did ONCE is not who they ARE. Anyone can snap or raise their voice on a bad day. Short-tempered means it happens often. Abusive means hurting someone again and again, which is serious and never OK.','ما فعله الإنسان مرة واحدة لا يعني أنه هكذا دائمًا. أي شخص قد يشخط أو يرفع صوته في يوم سيئ. أما العصبي فيغضب كثيرًا وبسرعة، والمسيء يؤذي الآخرين مرارًا، وهذا خطير ولا يُقبل أبدًا.','''He snapped at me'' describes one moment. ''He is short-tempered'' describes his personality. Don''t turn one moment into a label.','Psychologists separate a state (how someone feels or acts now) from a trait (how they usually are): Spielberger''s State-Trait Anger Expression Inventory measures state anger and trait anger separately.',91) on conflict (key) do update set title=excluded.title, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
insert into public.word_difference_parts (diff_key, word_id, explain, explain_ar, position) select 'moment-personality', (select id from public.words where lang = 'en' and lower(headword) = lower('Snapped at') order by (sense = '') desc limit 1), 'One moment: a short sharp word on a bad day.', 'لحظة: شخط مرة', 0 on conflict (diff_key, word_id) do update set explain = excluded.explain, explain_ar = excluded.explain_ar, position = excluded.position;
update public.words set tags = (select array(select distinct x from unnest(tags || array['≠ Snapped at (a moment) ≠ Short-tempered (a personality) ≠ Abusive (a pattern)']) x order by x)) where id = (select id from public.words where lang = 'en' and lower(headword) = lower('Snapped at') order by (sense = '') desc limit 1);
