insert into public.word_differences (key, title, unit, min_age, summary, summary_ar, example, note, position) values ('firm-aggressive','Firm ≠ Strict ≠ Aggressive',1,0,'Firm: clear and serious, you know they mean it, but calm. Strict: makes you follow the rules. Aggressive: pushes, shouts or threatens to get their way. Being firm or strict is not being angry.','الحازم واضح وجادّ وهادئ، والصارم يُلزمك بالقواعد، أما العدواني فيدفع ويصرخ ويهدّد ليفرض رأيه. الحزم والصرامة ليسا غضبًا.','''No, you can''t go out now. We''ll go tomorrow.'' said calmly is firm, not aggressive.',null,92) on conflict (key) do update set title=excluded.title, summary=excluded.summary, summary_ar=excluded.summary_ar, example=excluded.example, note=excluded.note, position=excluded.position;
